// Hand-maintained kill-switch service worker — no longer generated by
// vite-plugin-pwa (removed from vite.config.ts). Its only job is to
// unregister itself, purge every cache it finds, and force any open tab to
// reload once so the visitor lands on a real network request afterward.
//
// Why this is a plain static file now instead of a plugin output: as long
// as vite-plugin-pwa's registerSW.js kept running on every page load, it
// re-registered this same self-destroying script every time it unregistered
// itself, which forced ANOTHER reload, which re-ran registerSW.js again —
// an unconditional reload loop on every single visit, forever, not just for
// the handful of visitors who actually had something to clean up. That's
// almost certainly why fresh deploys kept failing to "show up": the loop's
// forced reload could race with (and sometimes lose to) the browser's own
// reload-loop throttling, leaving a stale render on screen.
//
// Removing the plugin stops any NEW registration from ever happening again
// (see index.html — there's no register call left anywhere in the app).
// This file only still needs to exist so a browser that already has an
// old registration (from before this fix) can find it on its own periodic
// update check, install it, and clean itself up one last time — nothing
// left afterward will ever re-register it. Safe to delete this file
// entirely once enough time has passed that no stale registrations remain
// (same reasoning as the selfDestroying:true config this replaced).
self.addEventListener('install', () => {
  self.skipWaiting();
});
self.addEventListener('activate', () => {
  self.registration
    .unregister()
    .then(() => self.clients.matchAll())
    .then((clients) => {
      clients.forEach((client) => {
        if (client instanceof WindowClient) client.navigate(client.url);
      });
    })
    .then(() => caches.keys())
    .then((cacheNames) => Promise.all(cacheNames.map((name) => caches.delete(name))));
});
